public class RustDWARFFunctionFixupTest : DWARFTestBase {

	/* @Test */
	public void testRustMethod_SetsRustCC()
    {
		addCompUnit(DW_LANG_Rust);

		DebugInfoEntry intDIE = addInt();
		newSubprogram("foo", intDIE, 0x410, 10).create();

		importFunctions();

